static inline const SomPerkDef *som_perk_def_by_id(unsigned id){
    unsigned lo=0,hi=SOM_PERK_DEF_COUNT;
    while(lo<hi){unsigned mid=(lo+hi)/2u;
        if(som_perk_defs[mid].id==id)return &som_perk_defs[mid];
        if(som_perk_defs[mid].id<id)lo=mid+1u;else hi=mid;}
    return 0;
}
static inline int som_perk_def_index(unsigned id){
    const SomPerkDef *d=som_perk_def_by_id(id);return d?(int)(d-som_perk_defs):-1;
}
